use expect_test::expect;

use super::ParityBatchCase;

fn github_interactive_insert_preserves_context_and_reuses_cache() -> ParityBatchCase {
    let elisp_form = r##"(gitignore-test-run
 "gitignore-templates-github-insert"
 'github
 (list
  (gitignore-test-fixture
   'github-list
   "https://api.github.com/gitignore/templates"
   '(("Accept" . "application/vnd.github.v3+json"))
   200 "OK" "application/json; charset=utf-8"
   gitignore-test-github-list-body)
  (gitignore-test-fixture
   'github-rust
   "https://api.github.com/gitignore/templates/Rust"
   nil 200 "OK" "application/json; charset=utf-8"
   gitignore-test-github-rust-body))
 (lambda (_root)
   (let ((buffer (gitignore-test-buffer " *gitignore-policy Ω*"))
         first second)
     (with-current-buffer buffer
       (insert "# Local overrides Ω\n\n# Keep below\n")
       (goto-char (point-min))
       (search-forward "# Keep below")
       (beginning-of-line)
       (setq gitignore-test-completion-choice "Rust")
       (let ((completing-read-function #'gitignore-test-completing-read))
         (call-interactively #'gitignore-templates-insert))
       (setq first
             (list :buffer (buffer-string) :point (point)
                   :modified (buffer-modified-p)))
       (gitignore-templates-insert "Rust")
       (setq second
             (list :buffer (buffer-string) :point (point)
                   :modified (buffer-modified-p))))
     (let ((source (cdr (assoc "Rust" gitignore-templates-alist))))
       (list
        :source-file (file-name-nondirectory
                      (locate-library "gitignore-templates"))
        :recordings
        (list :list (gitignore-test-recording
                     gitignore-test-github-list-body)
              :rust (gitignore-test-recording
                     gitignore-test-github-rust-body))
        :names
        (list :count (length gitignore-templates-names)
              :first (seq-take gitignore-templates-names 5)
              :last (copy-sequence (last gitignore-templates-names 5))
              :has-c++ (and (member "C++" gitignore-templates-names) t)
              :has-rust (and (member "Rust" gitignore-templates-names) t)
              :sha256
              (secure-hash 'sha256
                           (prin1-to-string gitignore-templates-names)))
        :source
        (list :characters (length source) :bytes (string-bytes source)
              :sha256 (secure-hash 'sha256 source)
              :terminal-newline (string-suffix-p "\n" source))
        :cache-keys (mapcar #'car gitignore-templates-alist)
        :first first :second second)))))"##;
    let expect = expect![[
        r##"OK (:result (:source-file "gitignore-templates.el" :recordings (:list (:characters 2080 :bytes 2080 :sha256 "8654753a0e86c1e193c7b62debbde5979ad3ebcdc1a738265f6663cb2ea08747") :rust (:characters 742 :bytes 742 :sha256 "041f805e49d991e9d3f742a84ee23fe6adc39749afbbb0c6e2e7bd8d699fd5ee")) :names (:count 161 :first ("AL" "Actionscript" "Ada" "AdventureGameStudio" "Agda") :last ("ZendFramework" "Zephir" "Zig" "bun" "ecu.test") :has-c++ t :has-rust t :sha256 "4e04c0a252d1dd10a7993a8d308c2acd10dc6387610b12af6c7f188a9c2d2ada") :source (:characters 684 :bytes 684 :sha256 "a38caa829ecdc7fdc18ad40bdb9d7e3da08b93cd712a558aabf524ac6e36037e" :terminal-newline t) :cache-keys ("Rust") :first (:buffer "# Local overrides Ω\n\n# Generated by Cargo\n# will have compiled files and executables\ndebug\ntarget\n\n# These are backup files generated by rustfmt\n**/*.rs.bk\n\n# MSVC Windows builds of rustc generate these, which store debugging information\n*.pdb\n\n# Generated by cargo mutants\n# Contains mutation testing data\n**/mutants.out*/\n\n# RustRover\n#  JetBrains specific template is maintained in a separate JetBrains.gitignore that can\n#  be found at https://github.com/github/gitignore/blob/main/Global/JetBrains.gitignore\n#  and can be added to the global gitignore or merged into this file.  For a more nuclear\n#  option (not recommended) you can uncomment the following to ignore the entire idea folder.\n#.idea/\n# Keep below\n" :point 706 :modified t) :second (:buffer "# Local overrides Ω\n\n# Generated by Cargo\n# will have compiled files and executables\ndebug\ntarget\n\n# These are backup files generated by rustfmt\n**/*.rs.bk\n\n# MSVC Windows builds of rustc generate these, which store debugging information\n*.pdb\n\n# Generated by cargo mutants\n# Contains mutation testing data\n**/mutants.out*/\n\n# RustRover\n#  JetBrains specific template is maintained in a separate JetBrains.gitignore that can\n#  be found at https://github.com/github/gitignore/blob/main/Global/JetBrains.gitignore\n#  and can be added to the global gitignore or merged into this file.  For a more nuclear\n#  option (not recommended) you can uncomment the following to ignore the entire idea folder.\n#.idea/\n# Generated by Cargo\n# will have compiled files and executables\ndebug\ntarget\n\n# These are backup files generated by rustfmt\n**/*.rs.bk\n\n# MSVC Windows builds of rustc generate these, which store debugging information\n*.pdb\n\n# Generated by cargo mutants\n# Contains mutation testing data\n**/mutants.out*/\n\n# RustRover\n#  JetBrains specific template is maintained in a separate JetBrains.gitignore that can\n#  be found at https://github.com/github/gitignore/blob/main/Global/JetBrains.gitignore\n#  and can be added to the global gitignore or merged into this file.  For a more nuclear\n#  option (not recommended) you can uncomment the following to ignore the entire idea folder.\n#.idea/\n# Keep below\n" :point 1390 :modified t)) :transport (:requests ((:id github-list :url "https://api.github.com/gitignore/templates" :method "GET" :headers (("Accept" . "application/vnd.github.v3+json")) :data nil :arguments nil) (:id github-rust :url "https://api.github.com/gitignore/templates/Rust" :method "GET" :headers nil :data nil :arguments nil)) :unused 0 :response-live (nil nil) :completions ((:prompt ".gitignore template: " :count 161 :first ("AL" "Actionscript" "Ada" "AdventureGameStudio") :last ("Zephir" "Zig" "bun" "ecu.test") :collection-sha256 "4e04c0a252d1dd10a7993a8d308c2acd10dc6387610b12af6c7f188a9c2d2ada" :predicate nil :require-match t :initial nil :history nil :default nil :inherit nil :choice "Rust"))) :cleanup (:owned-live nil :response-live nil :root-exists nil))"##
    ]];
    ParityBatchCase::value(
        "github_interactive_insert_preserves_context_and_reuses_cache",
        elisp_form,
        expect,
    )
}

fn gitignore_io_edits_and_creates_real_project_policy() -> ParityBatchCase {
    let elisp_form = r##"(gitignore-test-run
 "gitignore-templates-io-project"
 'gitignore.io
 (list
  (gitignore-test-fixture
   'gitignore-io-list "https://www.gitignore.io/api/list" nil
   200 "OK" "text/plain; charset=utf-8"
   gitignore-test-gitignore-io-list-body)
  (gitignore-test-fixture
   'gitignore-io-rust "https://www.gitignore.io/api/rust" nil
   200 "OK" "text/plain; charset=utf-8"
   gitignore-test-gitignore-io-rust-body))
 (lambda (root)
   (let* ((project (expand-file-name "release policy Ω/" root))
          (file (expand-file-name ".gitignore" project))
          (buffer (gitignore-test-buffer " *gitignore-io-policy*"))
          insert-state create-state existing-state)
     (make-directory project t)
     (with-current-buffer buffer
       (insert "dist/\n\n# Local exceptions Ω\n")
       (goto-char (point-min))
       (forward-line 1)
       (gitignore-templates-insert "rust")
       (setq insert-state
             (list :buffer (buffer-string) :point (point)
                   :modified (buffer-modified-p))))
     (let ((origin (current-buffer))
           (default-directory project))
       (setq create-state
             (list :return (gitignore-templates-new-file "rust")
                   :path (file-relative-name file root)
                   :bytes (string-bytes (gitignore-test-file-string file))
                   :sha256 (secure-hash 'sha256
                                        (gitignore-test-file-string file))
                   :mode (file-modes file)
                   :visiting (and (get-file-buffer file) t)
                   :same-current (eq origin (current-buffer))))
       (setq existing-state
             (list :condition
                   (gitignore-test-capture
                    (lambda () (gitignore-templates-new-file "rust")))
                   :unchanged
                   (equal (gitignore-test-file-string file)
                          gitignore-test-gitignore-io-rust-body))))
     (list
      :recordings
      (list :list (gitignore-test-recording
                   gitignore-test-gitignore-io-list-body)
            :rust (gitignore-test-recording
                   gitignore-test-gitignore-io-rust-body))
      :names
      (list :count (length gitignore-templates-names)
            :first (seq-take gitignore-templates-names 5)
            :last (copy-sequence (last gitignore-templates-names 5))
            :rust-case
            (list (and (member "rust" gitignore-templates-names) t)
                  (and (member "Rust" gitignore-templates-names) t)))
      :template
      (list :exact (equal (cdr (assoc "rust" gitignore-templates-alist))
                          gitignore-test-gitignore-io-rust-body)
            :bytes (string-bytes
                    (cdr (assoc "rust" gitignore-templates-alist))))
      :insert insert-state :create create-state :existing existing-state))))"##;
    let expect = expect![[
        r#"OK (:result (:recordings (:list (:characters 4941 :bytes 4941 :sha256 "c45471cc979c647279149bfa3e5544d8cdaa2c5d1bca94737ea1ad380200b885") :rust (:characters 626 :bytes 626 :sha256 "d192d67fece05ceafd683a251c3c82f4c246482158a39ac1abd5a714d23c6212")) :names (:count 571 :first ("1c" "1c-bitrix" "a-frame" "actionscript" "ada") :last ("zendframework" "zephir" "zig" "zsh" "zukencr8000") :rust-case (t nil)) :template (:exact t :bytes 626) :insert (:buffer "dist/\n# Created by https://www.toptal.com/developers/gitignore/api/rust\n# Edit at https://www.toptal.com/developers/gitignore?templates=rust\n\n### Rust ###\n# Generated by Cargo\n# will have compiled files and executables\ndebug/\ntarget/\n\n# Remove Cargo.lock from gitignore if creating an executable, leave it for libraries\n# More information here https://doc.rust-lang.org/cargo/guide/cargo-toml-vs-cargo-lock.html\nCargo.lock\n\n# These are backup files generated by rustfmt\n**/*.rs.bk\n\n# MSVC Windows builds of rustc generate these, which store debugging information\n*.pdb\n\n# End of https://www.toptal.com/developers/gitignore/api/rust\n\n# Local exceptions Ω\n" :point 633 :modified t) :create (:return nil :path "release policy Ω/.gitignore" :bytes 626 :sha256 "d192d67fece05ceafd683a251c3c82f4c246482158a39ac1abd5a714d23c6212" :mode 420 :visiting nil :same-current t) :existing (:condition (:signal user-error :data ("Can’t create ’[ORACLE-SANDBOX]/gitignore-templates-io-project/release policy Ω/.gitignore’, because it already exists")) :unchanged t)) :transport (:requests ((:id gitignore-io-list :url "https://www.gitignore.io/api/list" :method "GET" :headers nil :data nil :arguments nil) (:id gitignore-io-rust :url "https://www.gitignore.io/api/rust" :method "GET" :headers nil :data nil :arguments nil)) :unused 0 :response-live (nil nil) :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil))"#
    ]];
    ParityBatchCase::value(
        "gitignore_io_edits_and_creates_real_project_policy",
        elisp_form,
        expect,
    )
}

fn provider_switch_exposes_global_case_sensitive_caches() -> ParityBatchCase {
    let elisp_form = r##"(gitignore-test-run
 "gitignore-templates-provider-cache"
 'gitignore.io
 (list
  (gitignore-test-fixture
   'io-list-1 "https://www.gitignore.io/api/list" nil
   200 "OK" "text/plain; charset=utf-8"
   gitignore-test-gitignore-io-list-body)
  (gitignore-test-fixture
   'io-rust-1 "https://www.gitignore.io/api/rust" nil
   200 "OK" "text/plain; charset=utf-8"
   gitignore-test-gitignore-io-rust-body)
  (gitignore-test-fixture
   'github-list "https://api.github.com/gitignore/templates"
   '(("Accept" . "application/vnd.github.v3+json"))
   200 "OK" "application/json; charset=utf-8"
   gitignore-test-github-list-body)
  (gitignore-test-fixture
   'github-rust "https://api.github.com/gitignore/templates/Rust" nil
   200 "OK" "application/json; charset=utf-8"
   gitignore-test-github-rust-body)
  (gitignore-test-fixture
   'io-list-2 "https://www.gitignore.io/api/list" nil
   200 "OK" "text/plain; charset=utf-8"
   gitignore-test-gitignore-io-list-body)
  (gitignore-test-fixture
   'io-rust-2 "https://www.gitignore.io/api/rust" nil
   200 "OK" "text/plain; charset=utf-8"
   gitignore-test-gitignore-io-rust-body))
 (lambda (_root)
   (let (warm stale refreshed github-final io-final)
     (setq warm
           (list :names (gitignore-templates-names)
                 :rust-sha (secure-hash 'sha256
                                        (gitignore-templates "rust"))
                 :requests (length gitignore-test-requests)))
     (setq gitignore-templates-api 'github)
     (setq stale
           (list :same-names
                 (eq (gitignore-templates-names) (plist-get warm :names))
                 :lower-rust
                 (and (member "rust" gitignore-templates-names) t)
                 :upper-rust
                 (and (member "Rust" gitignore-templates-names) t)
                 :rust-sha (secure-hash 'sha256
                                        (gitignore-templates "rust"))
                 :uppercase
                 (gitignore-test-capture
                  (lambda () (gitignore-templates "Rust")))
                 :requests (length gitignore-test-requests)))
     (setq gitignore-templates-names nil)
     (setq refreshed (gitignore-templates-names))
     (setq github-final
           (list :names-count (length refreshed)
                 :lower-rust (and (member "rust" refreshed) t)
                 :upper-rust (and (member "Rust" refreshed) t)
                 :rust-sha (secure-hash 'sha256
                                        (gitignore-templates "Rust"))
                 :cache-keys (mapcar #'car gitignore-templates-alist)
                 :requests (length gitignore-test-requests)))
     (setq gitignore-templates-api 'gitignore.io
           gitignore-templates-names nil
           gitignore-templates-alist nil)
     (setq io-final
           (list :names-count (length (gitignore-templates-names))
                 :rust-sha (secure-hash 'sha256
                                        (gitignore-templates "rust"))
                 :cache-keys (mapcar #'car gitignore-templates-alist)
                 :requests (length gitignore-test-requests)))
     (list
      :warm
      (list :names-count (length (plist-get warm :names))
            :first (seq-take (plist-get warm :names) 3)
            :rust-sha (plist-get warm :rust-sha)
            :requests (plist-get warm :requests))
      :stale stale :github github-final :io io-final))))"##;
    let expect = expect![[
        r#"OK (:result (:warm (:names-count 571 :first ("1c" "1c-bitrix" "a-frame") :rust-sha "d192d67fece05ceafd683a251c3c82f4c246482158a39ac1abd5a714d23c6212" :requests 2) :stale (:same-names t :lower-rust t :upper-rust nil :rust-sha "d192d67fece05ceafd683a251c3c82f4c246482158a39ac1abd5a714d23c6212" :uppercase (:signal user-error :data ("Invaild template name Rust")) :requests 2) :github (:names-count 161 :lower-rust nil :upper-rust t :rust-sha "a38caa829ecdc7fdc18ad40bdb9d7e3da08b93cd712a558aabf524ac6e36037e" :cache-keys ("Rust" "rust") :requests 4) :io (:names-count 571 :rust-sha "d192d67fece05ceafd683a251c3c82f4c246482158a39ac1abd5a714d23c6212" :cache-keys ("rust") :requests 6)) :transport (:requests ((:id io-list-1 :url "https://www.gitignore.io/api/list" :method "GET" :headers nil :data nil :arguments nil) (:id io-rust-1 :url "https://www.gitignore.io/api/rust" :method "GET" :headers nil :data nil :arguments nil) (:id github-list :url "https://api.github.com/gitignore/templates" :method "GET" :headers (("Accept" . "application/vnd.github.v3+json")) :data nil :arguments nil) (:id github-rust :url "https://api.github.com/gitignore/templates/Rust" :method "GET" :headers nil :data nil :arguments nil) (:id io-list-2 :url "https://www.gitignore.io/api/list" :method "GET" :headers nil :data nil :arguments nil) (:id io-rust-2 :url "https://www.gitignore.io/api/rust" :method "GET" :headers nil :data nil :arguments nil)) :unused 0 :response-live (nil nil nil nil nil nil) :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil))"#
    ]];
    ParityBatchCase::value(
        "provider_switch_exposes_global_case_sensitive_caches",
        elisp_form,
        expect,
    )
}

fn validation_failures_precede_network_and_preserve_existing_policy() -> ParityBatchCase {
    let elisp_form = r##"(list
 (gitignore-test-run
  "gitignore-existing-file" 'gitignore.io nil
  (lambda (root)
    (let* ((file (expand-file-name ".gitignore" root))
           (bytes "# Preserve local policy Ω\n!important.log\n"))
      (write-region bytes nil file nil 'silent)
      (list :condition
            (gitignore-test-capture
             (lambda () (gitignore-templates-new-file "rust" root)))
            :bytes (gitignore-test-file-string file)
            :names gitignore-templates-names))))
 (gitignore-test-run
  "gitignore-invalid-inputs" 'unsupported-provider nil
  (lambda (_root)
    (let ((unknown
           (gitignore-test-capture #'gitignore-templates-names)))
      (setq gitignore-templates-api 'github
            gitignore-templates-names '("Rust"))
      (list :unknown unknown
            :invalid
            (gitignore-test-capture
             (lambda () (gitignore-templates "rust"))))))))"##;
    let expect = expect![[
        r##"OK ((:result (:condition (:signal user-error :data ("Can’t create ’[ORACLE-SANDBOX]/gitignore-existing-file/.gitignore’, because it already exists")) :bytes "# Preserve local policy Ω\n!important.log\n" :names nil) :transport (:requests nil :unused 0 :response-live nil :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil)) (:result (:unknown (:signal user-error :data ("Unknown API unsupported-provider")) :invalid (:signal user-error :data ("Invaild template name rust"))) :transport (:requests nil :unused 0 :response-live nil :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil)))"##
    ]];
    ParityBatchCase::value(
        "validation_failures_precede_network_and_preserve_existing_policy",
        elisp_form,
        expect,
    )
}

fn transport_and_parser_failures_preserve_callers_and_expose_cleanup() -> ParityBatchCase {
    let elisp_form = r##"(list
 (gitignore-test-run
  "gitignore-offline-signal" 'github
  (list
   (gitignore-test-outcome
    'offline "https://api.github.com/gitignore/templates"
    '(("Accept" . "application/vnd.github.v3+json"))
    'signal '(file-error "recorded offline transport")))
  (lambda (_root)
    (let ((buffer (gitignore-test-buffer " *gitignore-offline-caller*")))
      (with-current-buffer buffer (insert "unchanged Ω"))
      (list :condition
            (with-current-buffer buffer
              (gitignore-test-capture
               (lambda () (gitignore-templates-insert "Rust"))))
            :names gitignore-templates-names
            :templates gitignore-templates-alist
            :caller (with-current-buffer buffer (buffer-string))))))
 (gitignore-test-run
  "gitignore-nil-transport" 'gitignore.io
  (list
   (gitignore-test-outcome
    'nil-response "https://www.gitignore.io/api/list" nil 'return-nil nil))
 (lambda (_root)
    (list :condition (gitignore-test-capture #'gitignore-templates-names)
          :cache gitignore-templates-names))))"##;
    let expect = expect![[
        r#"OK ((:result (:condition (:signal file-error :data ("recorded offline transport")) :names nil :templates nil :caller "unchanged Ω") :transport (:requests ((:id offline :url "https://api.github.com/gitignore/templates" :method "GET" :headers (("Accept" . "application/vnd.github.v3+json")) :data nil :arguments nil)) :unused 0 :response-live nil :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil)) (:result (:condition (:signal wrong-type-argument :data (stringp nil)) :cache nil) :transport (:requests ((:id nil-response :url "https://www.gitignore.io/api/list" :method "GET" :headers nil :data nil :arguments nil)) :unused 0 :response-live nil :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil)))"#
    ]];
    ParityBatchCase::value(
        "transport_and_parser_failures_preserve_callers_and_expose_cleanup",
        elisp_form,
        expect,
    )
}

