fn missing_github_source_preserves_dangerous_whole_buffer_write() -> ParityBatchCase {
    let elisp_form = r##"(gitignore-test-run
  "gitignore-missing-source" 'github
  (list
   (gitignore-test-fixture
    'github-authentic-404
    "https://api.github.com/gitignore/templates/NeomacsParityMissing"
    nil 404 "Not Found" "application/json; charset=utf-8"
    gitignore-test-github-missing-body))
  (lambda (root)
    (let* ((name "NeomacsParityMissing")
           (file (expand-file-name ".gitignore" root))
           (buffer (gitignore-test-buffer " *gitignore-private-caller*"))
           insert-condition file-state)
      (setq gitignore-templates-names (list name))
      (with-current-buffer buffer
        (insert "PRIVATE CURRENT BUFFER Ω\n")
        (setq insert-condition
              (gitignore-test-capture
               (lambda () (gitignore-templates-insert name))))
        (setq file-state
              (list :return (gitignore-templates-new-file name root)
                    :bytes (gitignore-test-file-string file)
                    :visiting (and (get-file-buffer file) t)
                    :same-current (eq buffer (current-buffer)))))
      (list :recording (gitignore-test-recording
                        gitignore-test-github-missing-body)
            :insert insert-condition
            :cached (copy-tree gitignore-templates-alist)
            :file file-state))))"##;
    let expect = expect![[
        r#"OK (:result (:recording (:characters 111 :bytes 111 :sha256 "ef39fd9023238ffc04e9cbb43f079d20124a8f8838546a4d355ecb3b0ea89e21") :insert (:signal wrong-type-argument :data (char-or-string-p nil)) :cached (("NeomacsParityMissing")) :file (:return nil :bytes "PRIVATE CURRENT BUFFER Ω\n" :visiting nil :same-current t)) :transport (:requests ((:id github-authentic-404 :url "https://api.github.com/gitignore/templates/NeomacsParityMissing" :method "GET" :headers nil :data nil :arguments nil)) :unused 0 :response-live (nil) :completions nil) :cleanup (:owned-live nil :response-live nil :root-exists nil))"#
    ]];
    ParityBatchCase::value(
        "missing_github_source_preserves_dangerous_whole_buffer_write",
        elisp_form,
        expect,
    )
}

pub(super) fn public_workflow_cases() -> Vec<ParityBatchCase> {
    vec![
        github_interactive_insert_preserves_context_and_reuses_cache(),
        gitignore_io_edits_and_creates_real_project_policy(),
        provider_switch_exposes_global_case_sensitive_caches(),
        validation_failures_precede_network_and_preserve_existing_policy(),
        transport_and_parser_failures_preserve_callers_and_expose_cleanup(),
        truncated_json_exposes_parser_cache_and_response_cleanup_boundary(),
        missing_github_source_preserves_dangerous_whole_buffer_write(),
    ]
}
